1	// Package chainledger implements the on-chain data governance core.
2	package chainledger
3	
4	import (
5		"bytes"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"sort"
10		"strings"
11	)
12	
13	// PlanChange is one record in a lineage adjustment plan: the dataset name and
14	// the complete list of its direct upstreams after the batch is applied.
15	//
16	// A change may name a dataset that does not exist yet (it is registered) or an
17	// existing dataset (its direct upstreams are replaced wholesale). Datasets not
18	// mentioned in the plan keep their current direct upstreams.
19	type PlanChange struct {
20		Name      string   `json:"name"`
21		Upstreams []string `json:"upstreams"`
22	}
23	
24	// Plan is a batch of lineage adjustments read from a JSON file.
25	//
26	// Removals names datasets that must be absent from the final graph. Deleting a
27	// name that does not currently exist is a no-op (it is not reported as an
28	// actual removal), so a successful plan can be applied again with empty change
29	// and impact lists. A name listed in Removals must not also appear in Changes.
30	type Plan struct {
31		Changes  []PlanChange `json:"changes"`
32		Removals []string     `json:"removals"`
33	}
34	
35	// Relation is a directed lineage edge: Upstream -> Downstream, meaning the
36	// downstream dataset derives from the upstream dataset.
37	type Relation struct {
38		Upstream   string `json:"upstream"`
39		Downstream string `json:"downstream"`
40	}
41	
42	// GraphDataset is one dataset record in the on-disk graph JSON.
43	type GraphDataset struct {
44		Name      string   `json:"name"`
45		Upstreams []string `json:"upstreams"`
46	}
47	
48	// GraphFile is the on-disk JSON representation of a lineage graph.
49	type GraphFile struct {
50		Datasets []GraphDataset `json:"datasets"`
51	}
52	
53	// BatchReport is the deterministic report produced by preview and apply.
54	//
55	// All slices are non-nil (empty lists encode as [] in JSON). Datasets and name
56	// lists are sorted by name byte order; relation lists are sorted by upstream
57	// then downstream.
58	type BatchReport struct {
59		FinalGraph          GraphFile  `json:"finalGraph"`
60		NewDatasets         []string   `json:"newDatasets"`
61		ChangedDatasets     []string   `json:"changedDatasets"`
62		RemovedDatasets     []string   `json:"removedDatasets"`
63		AddedRelations      []Relation `json:"addedRelations"`
64		RemovedRelations    []Relation `json:"removedRelations"`
65		AffectedDownstreams []string   `json:"affectedDownstreams"`
66	}
67	
68	// graphAdjacency derives the normalized parent map from the in-memory graph.
69	// It rejects nil lineage nodes, empty names, and references to upstreams that
70	// are not registered; the name/reference rules are the shared ones from
71	// normalizeDatasets and validateAdjacencyReferences, also used by the file and
72	// snapshot readers. It does not check for cycles; use validateAcyclic for that.
73	func graphAdjacency(graph map[string]*Lineage) (adjacency, error) {
74		if graph == nil {
75			return nil, fmt.Errorf("%w: create the graph map with make before validating", ErrNotInitialized)
76		}
77		records := make([]GraphDataset, 0, len(graph))
78		for name, entry := range graph {
79			if entry == nil {
80				return nil, fmt.Errorf("%w: dataset %q points to a nil lineage node", ErrInvalidArgument, name)
81			}
82			if name == "" {
83				return nil, fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
84			}
85			records = append(records, GraphDataset{Name: name, Upstreams: entry.Parents})
86		}
87		adj, err := normalizeDatasets(records)
88		if err != nil {
89			return nil, err
90		}
91		if err := validateAdjacencyReferences(adj); err != nil {
92			return nil, err
93		}
94		return adj, nil
95	}
96	
97	// ValidateGraph checks the in-memory graph for structural problems: nil nodes,
98	// empty names, missing upstreams, and cycles. It does not mutate the graph.
99	//
100	// A graph that fails validation cannot be used as the basis for a batch: an
101	// adjustment plan must not be allowed to paper over pre-existing corruption.
102	func ValidateGraph(graph map[string]*Lineage) error {
103		adj, err := graphAdjacency(graph)
104		if err != nil {
105			return err
106		}
107		return validateAcyclic(adj)
108	}
109	
110	// computeBatch validates the graph and plan, then computes the final adjacency
111	// and the diff report. It does not mutate graph. The returned adjacency is the
112	// graph as it will be after the batch; callers that want to commit it should
113	// pass it to applyAdjacency.
114	func computeBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, adjacency, error) {
115		if err := ValidateGraph(graph); err != nil {
116			return nil, nil, err
117		}
118		original, err := graphAdjacency(graph)
119		if err != nil {
120			return nil, nil, err
121		}
122	
123		// Validate the plan: empty names and duplicate declarations reject the
124		// whole batch, naming the dataset and the reason.
125		declarations := make(map[string]int, len(plan.Changes))
126		for _, change := range plan.Changes {
127			if change.Name == "" {
128				return nil, nil, fmt.Errorf("%w: plan contains a dataset with an empty name", ErrInvalidArgument)
129			}
130			declarations[change.Name]++
131			if declarations[change.Name] > 1 {
132				return nil, nil, fmt.Errorf("%w: dataset %q is declared %d times in the plan", ErrInvalidArgument, change.Name, declarations[change.Name])
133			}
134		}
135	
136		// Validate removals: empty names, duplicate names, and names also declared
137		// as changes all reject the whole batch with the name and reason.
138		removalDecls := make(map[string]int, len(plan.Removals))
139		for _, name := range plan.Removals {
140			if name == "" {
141				return nil, nil, fmt.Errorf("%w: plan removals contain a dataset with an empty name", ErrInvalidArgument)
142			}
143			removalDecls[name]++
144			if removalDecls[name] > 1 {
145				return nil, nil, fmt.Errorf("%w: dataset %q is listed %d times in removals", ErrInvalidArgument, name, removalDecls[name])
146			}
147			if _, ok := declarations[name]; ok {
148				return nil, nil, fmt.Errorf("%w: dataset %q appears in both changes and removals", ErrInvalidArgument, name)
149			}
150		}
151	
152		// Build the final adjacency: start from the original parents, replace each
153		// planned dataset's parents with its normalized upstreams.
154		final := make(adjacency, len(original)+len(plan.Changes))
155		for name, parents := range original {
156			final[name] = append([]string(nil), parents...)
157		}
158		for name := range removalDecls {
159			delete(final, name)
160		}
161		var newNames []string
162		var changedNames []string
163		for _, change := range plan.Changes {
164			wanted := uniqueSorted(change.Upstreams)
165			old, existed := original[change.Name]
166			switch {
167			case !existed:
168				newNames = append(newNames, change.Name)
169			case !stringSliceEqual(old, wanted):
170				changedNames = append(changedNames, change.Name)
171			}
172			final[change.Name] = wanted
173		}
174		sort.Strings(newNames)
175		sort.Strings(changedNames)
176	
177		// Datasets actually removed: names in removals that existed in the
178		// original graph. Deleting a name that does not exist is a no-op and is
179		// not reported, so a successful plan can be applied again with empty lists.
180		var removedNames []string
181		for name := range removalDecls {
182			if _, existed := original[name]; existed {
183				removedNames = append(removedNames, name)
184			}
185		}
186		sort.Strings(removedNames)
187	
188		// Every upstream must resolve to a dataset that exists in the FINAL graph
189		// (new datasets may reference each other regardless of plan order; a
190		// retained dataset that still references a deleted name is rejected here,
191		// with both the referrer and the referenced name in the error). Iterate
192		// over sorted names so the reported pair is deterministic.
193		names := make([]string, 0, len(final))
194		for name := range final {
195			names = append(names, name)
196		}
197		sort.Strings(names)
198		for _, name := range names {
199			for _, parent := range final[name] {
200				if _, ok := final[parent]; !ok {
201					return nil, nil, fmt.Errorf("%w: dataset %q references upstream %q which does not exist in the final graph", ErrNotFound, name, parent)
202				}
203			}
204		}
205		// The final graph must be acyclic, judged after all replacements.
206		if err := validateAcyclic(final); err != nil {
207			return nil, nil, err
208		}
209	
210		added, removed := diffRelations(original, final)
211		affected := affectedDownstreams(original, final, newNames, changedNames, removedNames)
212	
213		report := &BatchReport{
214			FinalGraph:          GraphFile{Datasets: adjacencyToDatasets(final)},
215			NewDatasets:         newNames,
216			ChangedDatasets:     changedNames,
217			RemovedDatasets:     removedNames,
218			AddedRelations:      added,
219			RemovedRelations:    removed,
220			AffectedDownstreams: affected,
221		}
222		// Guarantee non-nil slices so JSON encodes empty lists as [].
223		if report.NewDatasets == nil {
224			report.NewDatasets = []string{}
225		}
226		if report.ChangedDatasets == nil {
227			report.ChangedDatasets = []string{}
228		}
229		if report.RemovedDatasets == nil {
230			report.RemovedDatasets = []string{}
231		}
232		if report.AddedRelations == nil {
233			report.AddedRelations = []Relation{}
234		}
235		if report.RemovedRelations == nil {
236			report.RemovedRelations = []Relation{}
237		}
238		if report.AffectedDownstreams == nil {
239			report.AffectedDownstreams = []string{}
240		}
241		return report, final, nil
242	}
243	
244	// PreviewBatch validates the graph and plan and returns the report WITHOUT
245	// mutating graph. Preview and apply for the same graph and plan produce
246	// identical reports.
247	func PreviewBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
248		report, _, err := computeBatch(graph, plan)
249		return report, err
250	}
251	
252	// ApplyBatch validates the plan, applies it to graph, and returns the report.
253	// On rejection, graph is left completely unchanged.
254	func ApplyBatch(graph map[string]*Lineage, plan Plan) (*BatchReport, error) {
255		report, final, err := computeBatch(graph, plan)
256		if err != nil {
257			return nil, err
258		}
259		applyAdjacency(graph, final)
260		return report, nil
261	}
262	
263	// applyAdjacency rewrites the in-memory graph to match the final adjacency:
264	// nodes absent from final are removed, parents are replaced, and children are
265	// rebuilt from the parent edges.
266	func applyAdjacency(graph map[string]*Lineage, final adjacency) {
267		for name := range graph {
268			if _, ok := final[name]; !ok {
269				delete(graph, name)
270			}
271		}
272		for name, parents := range final {
273			entry := graph[name]
274			if entry == nil {
275				entry = &Lineage{}
276				graph[name] = entry
277			}
278			entry.Dataset = name
279			entry.Parents = append([]string(nil), parents...)
280			entry.Children = nil
281		}
282		for name, parents := range final {
283			for _, parent := range parents {
284				graph[parent].Children = append(graph[parent].Children, name)
285			}
286		}
287		for name := range graph {
288			graph[name].Children = uniqueSorted(graph[name].Children)
289		}
290	}
291	
292	// diffRelations returns the directed edges present in final but not original
293	// (added) and present in original but not final (removed). Both lists are
294	// sorted by upstream then downstream.
295	func diffRelations(original, final adjacency) (added, removed []Relation) {
296		origEdges := edgeSet(original)
297		finalEdges := edgeSet(final)
298		for e := range finalEdges {
299			if !origEdges[e] {
300				added = append(added, e)
301			}
302		}
303		for e := range origEdges {
304			if !finalEdges[e] {
305				removed = append(removed, e)
306			}
307		}
308		sortRelations(added)
309		sortRelations(removed)
310		return added, removed
311	}
312	
313	// edgeSet collapses the adjacency into a set of upstream->downstream edges.
314	func edgeSet(adj adjacency) map[Relation]bool {
315		set := make(map[Relation]bool)
316		for downstream, parents := range adj {
317			for _, upstream := range parents {
318				set[Relation{Upstream: upstream, Downstream: downstream}] = true
319			}
320		}
321		return set
322	}
323	
324	// sortRelations sorts by upstream then downstream.
325	func sortRelations(rels []Relation) {
326		sort.Slice(rels, func(i, j int) bool {
327			if rels[i].Upstream != rels[j].Upstream {
328				return rels[i].Upstream < rels[j].Upstream
329			}
330			return rels[i].Downstream < rels[j].Downstream
331		})
332	}
333	
334	// affectedDownstreams computes the impact set: starting from the seed datasets
335	// (new, actually changed, or actually removed), follow downstream (children)
336	// edges in BOTH the original and the final graphs. Datasets that are
337	// themselves seeds are excluded from the output; every other reachable dataset
338	// is included once.
339	//
340	// Walking both graphs matters when relations are deleted: a dataset that was
341	// reachable downstream before the change (and thus loses a lineage path) is
342	// still affected even if the edge is gone in the final graph. Removed datasets
343	// are seeds too, so a downstream that lost its upstream node is counted.
344	func affectedDownstreams(original, final adjacency, newNames, changedNames, removedNames []string) []string {
345		seeds := make(map[string]bool, len(newNames)+len(changedNames)+len(removedNames))
346		for _, name := range newNames {
347			seeds[name] = true
348		}
349		for _, name := range changedNames {
350			seeds[name] = true
351		}
352		for _, name := range removedNames {
353			seeds[name] = true
354		}
355	
356		origChildren := invertAdjacency(original)
357		finalChildren := invertAdjacency(final)
358	
359		seen := make(map[string]bool)
360		queue := make([]string, 0, len(seeds))
361		for seed := range seeds {
362			queue = append(queue, seed)
363		}
364		for len(queue) > 0 {
365			node := queue[0]
366			queue = queue[1:]
367			for _, child := range origChildren[node] {
368				if !seen[child] {
369					seen[child] = true
370					queue = append(queue, child)
371				}
372			}
373			for _, child := range finalChildren[node] {
374				if !seen[child] {
375					seen[child] = true
376					queue = append(queue, child)
377				}
378			}
379		}
380	
381		out := make([]string, 0, len(seen))
382		for name := range seen {
383			if !seeds[name] {
384				out = append(out, name)
385			}
386		}
387		sort.Strings(out)
388		return out
389	}
390	
391	// invertAdjacency maps each dataset to the datasets that depend on it (its
392	// children), with each child list sorted by name.
393	func invertAdjacency(adj adjacency) map[string][]string {
394		children := make(map[string][]string, len(adj))
395		for name, parents := range adj {
396			for _, parent := range parents {
397				children[parent] = append(children[parent], name)
398			}
399		}
400		for name := range children {
401			sort.Strings(children[name])
402		}
403		return children
404	}
405	
406	// adjacencyToDatasets renders the final adjacency as sorted, JSON-ready
407	// records with non-nil upstream lists.
408	func adjacencyToDatasets(adj adjacency) []GraphDataset {
409		names := make([]string, 0, len(adj))
410		for name := range adj {
411			names = append(names, name)
412		}
413		sort.Strings(names)
414		ds := make([]GraphDataset, 0, len(names))
415		for _, name := range names {
416			parents := adj[name]
417			if parents == nil {
418				parents = []string{}
419			}
420			ds = append(ds, GraphDataset{Name: name, Upstreams: parents})
421		}
422		return ds
423	}
424	
425	// stringSliceEqual reports whether a and b contain the same strings in the
426	// same order. Both are expected to be sorted and duplicate-free.
427	func stringSliceEqual(a, b []string) bool {
428		if len(a) != len(b) {
429			return false
430		}
431		for i := range a {
432			if a[i] != b[i] {
433				return false
434			}
435		}
436		return true
437	}
438	
439	// MarshalGraphFile serializes the in-memory graph to the on-disk JSON format.
440	// The graph must be valid; an invalid graph returns an error.
441	func MarshalGraphFile(graph map[string]*Lineage) ([]byte, error) {
442		adj, err := graphAdjacency(graph)
443		if err != nil {
444			return nil, err
445		}
446		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
447		return json.MarshalIndent(gf, "", "  ")
448	}
449	
450	// UnmarshalGraphFile parses the on-disk graph JSON and rebuilds the in-memory
451	// graph (parents and derived children). The graph is checked with the same
452	// structural rules a snapshot enforces (empty names, duplicate datasets,
453	// missing upstreams, and cycles); a structurally invalid graph is rejected so
454	// it cannot be used as the basis for a batch. As in a snapshot, a known field
455	// declared twice within the same object — datasets in the graph object, name
456	// or upstreams in a dataset record — is ambiguous and rejects the whole file,
457	// even when the duplicates carry identical values.
458	func UnmarshalGraphFile(data []byte) (map[string]*Lineage, error) {
459		if err := checkGraphFileDuplicateFields(data); err != nil {
460			return nil, err
461		}
462		var gf GraphFile
463		if err := json.Unmarshal(data, &gf); err != nil {
464			return nil, fmt.Errorf("invalid graph JSON: %w", err)
465		}
466		adj, err := validateGraphStructureFromFile(gf.Datasets)
467		if err != nil {
468			return nil, err
469		}
470		// Rebuild children from the parent edges so the in-memory graph is
471		// consistent regardless of how the file was produced.
472		return lineageFromAdjacency(adj), nil
473	}
474	
475	// UnmarshalPlan parses the plan JSON. The plan structure (empty names,
476	// duplicate declarations) is validated later by computeBatch so that preview
477	// and apply share identical rejection behavior.
478	//
479	// A known field declared twice within the same object — changes or removals
480	// at the top level, name or upstreams inside one change record — is
481	// ambiguous: the reader would silently keep only the last declaration and
482	// drop the earlier adjustment. The whole plan is refused instead, even when
483	// the duplicates carry identical values, one is null, or the surviving value
484	// is a legal empty list. Field names are recognized the same way the decoder
485	// resolves them (after JSON unescaping, with Unicode case folding), so a
486	// second declaration spelled "Changes" or "changes" still collides;
487	// dataset names themselves stay case-sensitive. Unknown fields keep their
488	// ignore-everything behavior and may repeat freely.
489	func UnmarshalPlan(data []byte) (Plan, error) {
490		var p Plan
491		if err := checkPlanDuplicateFields(data); err != nil {
492			return p, err
493		}
494		if err := json.Unmarshal(data, &p); err != nil {
495			return p, fmt.Errorf("invalid plan JSON: %w", err)
496		}
497		return p, nil
498	}
499	
500	// checkPlanDuplicateFields rejects a plan in which a known field is declared
501	// more than once within the same object: changes or removals at the top
502	// level, and name or upstreams inside each change record. It reuses the
503	// snapshot/graph scanner (UseNumber decoding, case-folded key matching,
504	// abort-on-malformed), so a plan can never be judged differently from the
505	// other documents about what counts as a repeated field, and an oversized
506	// number buried in an ignored unknown field cannot hide a later duplicate.
507	// Documents not shaped like a plan are left to the regular parse.
508	func checkPlanDuplicateFields(data []byte) error {
509		dec := json.NewDecoder(bytes.NewReader(data))
510		dec.UseNumber()
511		err := checkPlanTopLevel(dec)
512		if errors.Is(err, errAbortScan) {
513			return nil
514		}
515		return err
516	}
517	
518	// checkPlanTopLevel scans the top-level plan object for repeated
519	// changes/removals declarations, descending into the changes array.
520	func checkPlanTopLevel(dec *json.Decoder) error {
521		tok, err := scanToken(dec)
522		if err != nil {
523			return err
524		}
525		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
526			return nil // not an object: the regular parse reports the type error
527		}
528		seen := make(map[string]bool, 2)
529		for dec.More() {
530			key, err := scanKey(dec)
531			if err != nil {
532				return err
533			}
534			field, known := planField(key)
535			if known {
536				if seen[field] {
537					return duplicateFieldError(field, "at the top level of the plan")
538				}
539				seen[field] = true
540			}
541			if field == "changes" {
542				if err := checkChangesValue(dec); err != nil {
543					return err
544				}
545			} else if err := skipValue(dec); err != nil {
546				return err
547			}
548		}
549		_, err = scanToken(dec) // closing '}'
550		return err
551	}
552	
553	// checkChangesValue scans one changes array, checking every record that is
554	// an object for repeated name/upstreams declarations.
555	func checkChangesValue(dec *json.Decoder) error {
556		tok, err := scanToken(dec)
557		if err != nil {
558			return err
559		}
560		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
561			return skipRest(dec, tok) // not an array: the regular parse reports it
562		}
563		for index := 0; dec.More(); index++ {
564			if err := checkChangeRecord(dec, index); err != nil {
565				return err
566			}
567		}
568		_, err = scanToken(dec) // closing ']'
569		return err
570	}
571	
572	// checkChangeRecord scans one element of the changes array. If it is an
573	// object, name and upstreams must each be declared at most once.
574	func checkChangeRecord(dec *json.Decoder, index int) error {
575		tok, err := scanToken(dec)
576		if err != nil {
577			return err
578		}
579		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
580			return skipRest(dec, tok) // not an object: the regular parse reports it
581		}
582		seen := make(map[string]bool, 2)
583		for dec.More() {
584			key, err := scanKey(dec)
585			if err != nil {
586				return err
587			}
588			// A change record carries the same fields as a dataset record, so the
589			// shared datasetField mapping keeps the two readers in lockstep.
590			if field, known := datasetField(key); known {
591				if seen[field] {
592					return duplicateFieldError(field, fmt.Sprintf("in the change record at index %d of \"changes\"", index))
593				}
594				seen[field] = true
595			}
596			if err := skipValue(dec); err != nil {
597				return err
598			}
599		}
600		_, err = scanToken(dec) // closing '}'
601		return err
602	}
603	
604	// planField maps a top-level plan key to the canonical name of the plan field
605	// it selects, matching the decoder's case-insensitive field lookup.
606	func planField(key string) (string, bool) {
607		switch {
608		case strings.EqualFold(key, "changes"):
609			return "changes", true
610		case strings.EqualFold(key, "removals"):
611			return "removals", true
612		}
613		return "", false
614	}
615

