1	// Package chainledger implements the on-chain data governance core.
2	//
3	// This file adds local lineage snapshots: a snapshot freezes one graph as a
4	// versioned, content-addressed JSON document, and two snapshots can be compared
5	// read-only. Every byte a snapshot writes is determined solely by the graph's
6	// semantics — dataset names and their direct upstreams — never by record
7	// order, upstream order, duplicate upstreams, JSON whitespace, save time, or
8	// file path.
9	package chainledger
10	
11	import (
12		"bytes"
13		"crypto/sha256"
14		"encoding/hex"
15		"encoding/json"
16		"errors"
17		"fmt"
18		"sort"
19		"strings"
20	)
21	
22	// SnapshotFormatVersion is the only on-disk snapshot format understood.
23	const SnapshotFormatVersion = 1
24	
25	// SnapshotFile is the on-disk representation of one frozen lineage graph.
26	//
27	// FormatVersion is fixed at 1. ContentID addresses the graph semantics and is
28	// verified against Graph on every read; Graph carries the complete graph.
29	type SnapshotFile struct {
30		FormatVersion int       `json:"formatVersion"`
31		ContentID     string    `json:"contentId"`
32		Graph         GraphFile `json:"graph"`
33	}
34	
35	// RootSourceChange reports that one dataset present in BOTH versions reaches a
36	// different set of root sources. OldRoots and NewRoots are sorted by name and
37	// never nil, so empty root sets encode as [] rather than null.
38	type RootSourceChange struct {
39		Dataset  string   `json:"dataset"`
40		OldRoots []string `json:"oldRoots"`
41		NewRoots []string `json:"newRoots"`
42	}
43	
44	// CompareReport is the deterministic, read-only diff of two snapshots read in
45	// the fixed direction old -> new.
46	//
47	// NewDatasets and RemovedDatasets list nodes present on only one side.
48	// ChangedDatasets lists datasets present on both sides whose direct upstream
49	// set actually changed. AddedRelations and RemovedRelations list every
50	// directed edge present on only one side, including edges that vanish because
51	// one endpoint node was removed. RootSourceChanges covers only datasets common
52	// to both versions whose reachable root set differs; added or removed datasets
53	// never appear there.
54	type CompareReport struct {
55		NewDatasets       []string           `json:"newDatasets"`
56		RemovedDatasets   []string           `json:"removedDatasets"`
57		ChangedDatasets   []string           `json:"changedDatasets"`
58		AddedRelations    []Relation         `json:"addedRelations"`
59		RemovedRelations  []Relation         `json:"removedRelations"`
60		RootSourceChanges []RootSourceChange `json:"rootSourceChanges"`
61	}
62	
63	// contentIDPrefix names the hash algorithm used for content addressing.
64	const contentIDPrefix = "sha256:"
65	
66	// canonicalGraph serializes the graph's semantics deterministically: datasets
67	// sorted by name byte order with sorted, duplicate-free upstream lists, compact
68	// JSON with no insignificant whitespace. Two semantically equal graphs always
69	// produce identical bytes.
70	func canonicalGraph(adj adjacency) ([]byte, error) {
71		gf := GraphFile{Datasets: adjacencyToDatasets(adj)}
72		return json.Marshal(gf)
73	}
74	
75	// computeContentID returns the content identifier of the graph bytes:
76	// "sha256:" followed by the lowercase hex SHA-256 digest.
77	func computeContentID(canonical []byte) string {
78		sum := sha256.Sum256(canonical)
79		return contentIDPrefix + hex.EncodeToString(sum[:])
80	}
81	
82	// BuildSnapshot validates graph and freezes it into a SnapshotFile with format
83	// version 1 and the matching content identifier. It does not mutate graph. The
84	// returned document and its serialized bytes depend only on graph semantics.
85	func BuildSnapshot(graph map[string]*Lineage) (*SnapshotFile, error) {
86		if err := ValidateGraph(graph); err != nil {
87			return nil, err
88		}
89		adj, err := graphAdjacency(graph)
90		if err != nil {
91			return nil, err
92		}
93		canonical, err := canonicalGraph(adj)
94		if err != nil {
95			return nil, err
96		}
97		return &SnapshotFile{
98			FormatVersion: SnapshotFormatVersion,
99			ContentID:     computeContentID(canonical),
100			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
101		}, nil
102	}
103	
104	// MarshalSnapshot serializes a snapshot the same way for every save: indented
105	// JSON keyed by struct field order, terminated by a single newline.
106	func MarshalSnapshot(snap *SnapshotFile) ([]byte, error) {
107		var buf bytes.Buffer
108		enc := json.NewEncoder(&buf)
109		enc.SetIndent("", "  ")
110		enc.SetEscapeHTML(false)
111		if err := enc.Encode(snap); err != nil {
112			return nil, err
113		}
114		return buf.Bytes(), nil
115	}
116	
117	// rawSnapshot mirrors SnapshotFile but keeps each field raw so ParseSnapshot
118	// can distinguish "field absent" from "field present with a zero value"
119	// (e.g. a missing formatVersion must be rejected rather than read as 0).
120	type rawSnapshot struct {
121		FormatVersion json.RawMessage `json:"formatVersion"`
122		ContentID     json.RawMessage `json:"contentId"`
123		Graph         json.RawMessage `json:"graph"`
124	}
125	
126	// isJSONNull reports whether a raw JSON value is the literal null.
127	func isJSONNull(raw json.RawMessage) bool {
128		return string(bytes.TrimSpace(raw)) == "null"
129	}
130	
131	// ParseSnapshot parses and strictly validates one snapshot document: required
132	// fields must be present and well-typed, no known field may be declared twice
133	// within the same object (even with identical values, a null first, or a
134	// spelling equivalent under Unicode case folding or JSON escaping), the
135	// format version must be supported, the embedded graph must be structurally
136	// valid (no empty names, duplicate datasets, missing upstreams, or cycles),
137	// and the content identifier must correspond exactly to the graph. A
138	// tampered, corrupt, or otherwise invalid snapshot is rejected, so a bad file
139	// can never be trusted as a version.
140	func ParseSnapshot(data []byte) (*SnapshotFile, error) {
141		if err := checkDuplicateFields(data); err != nil {
142			return nil, err
143		}
144		var raw rawSnapshot
145		if err := json.Unmarshal(data, &raw); err != nil {
146			return nil, fmt.Errorf("invalid snapshot JSON: %w", err)
147		}
148		if len(raw.FormatVersion) == 0 {
149			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "formatVersion")
150		}
151		if len(raw.ContentID) == 0 {
152			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "contentId")
153		}
154		if len(raw.Graph) == 0 {
155			return nil, fmt.Errorf("%w: snapshot is missing required field %q", ErrInvalidArgument, "graph")
156		}
157		// An explicit JSON null is present-but-untyped and must not be silently
158		// treated as a zero value (in particular, graph:null must not read as an
159		// empty graph).
160		if isJSONNull(raw.FormatVersion) {
161			return nil, fmt.Errorf("%w: snapshot field %q must be a number, not null", ErrInvalidArgument, "formatVersion")
162		}
163		if isJSONNull(raw.ContentID) {
164			return nil, fmt.Errorf("%w: snapshot field %q must be a string, not null", ErrInvalidArgument, "contentId")
165		}
166		if isJSONNull(raw.Graph) {
167			return nil, fmt.Errorf("%w: snapshot field %q must be an object, not null", ErrInvalidArgument, "graph")
168		}
169	
170		var version int
171		if err := json.Unmarshal(raw.FormatVersion, &version); err != nil {
172			return nil, fmt.Errorf("%w: snapshot field %q must be a number: %v", ErrInvalidArgument, "formatVersion", err)
173		}
174		if version != SnapshotFormatVersion {
175			return nil, fmt.Errorf("%w: unsupported snapshot format version %d, supported version is %d", ErrInvalidArgument, version, SnapshotFormatVersion)
176		}
177	
178		var contentID string
179		if err := json.Unmarshal(raw.ContentID, &contentID); err != nil {
180			return nil, fmt.Errorf("%w: snapshot field %q must be a string", ErrInvalidArgument, "contentId")
181		}
182		if contentID == "" {
183			return nil, fmt.Errorf("%w: snapshot field %q must not be empty", ErrInvalidArgument, "contentId")
184		}
185	
186		var gf GraphFile
187		if err := json.Unmarshal(raw.Graph, &gf); err != nil {
188			return nil, fmt.Errorf("invalid graph in snapshot: %w", err)
189		}
190		// The embedded graph obeys exactly the same structural rules as a
191		// standalone graph file, so the two readers can never judge one graph
192		// differently.
193		adj, err := validateGraphStructureFromFile(gf.Datasets)
194		if err != nil {
195			return nil, err
196		}
197	
198		canonical, err := canonicalGraph(adj)
199		if err != nil {
200			return nil, err
201		}
202		if want := computeContentID(canonical); contentID != want {
203			return nil, fmt.Errorf("%w: content identifier %q does not match the graph (expected %q); the snapshot was altered or corrupted", ErrInvalidArgument, contentID, want)
204		}
205	
206		return &SnapshotFile{
207			FormatVersion: version,
208			ContentID:     contentID,
209			Graph:         GraphFile{Datasets: adjacencyToDatasets(adj)},
210		}, nil
211	}
212	
213	// errAbortScan stops the duplicate-field scan when the document is too
214	// malformed to keep walking; the regular parse then reports the syntax or
215	// type error instead.
216	var errAbortScan = errors.New("chainledger: abort duplicate field scan")
217	
218	// checkDuplicateFields rejects a snapshot in which a known field is declared
219	// more than once within the same object: formatVersion, contentId, and graph
220	// at the top level, datasets inside graph, and name and upstreams inside each
221	// dataset record. A repeated field is ambiguous — the reader would silently
222	// keep only one declaration — so the whole snapshot is refused even when the
223	// duplicates carry identical values, the first is null, or the surviving value
224	// would pass every other check.
